    const dialog=document.querySelector('#reader');dialog.classList.add('runner-view');document.querySelector('#reader-label').textContent='NEON RUN / ROGUE PROTOCOL';
    document.querySelector('#reader-content').innerHTML=`<div class="runner-shell"><div class="runner-heading"><div><p class="eyebrow">PROJECT 001 / RUN · GUN · EVOLVE</p><h2>夜城疾跑 <span>ROGUE PROTOCOL</span></h2></div><label class="runner-mode-label">任务 / 演练<select id="run-mode" aria-label="游戏模式"><option value="ranked">正式任务 · 第1关起</option><option value="p3">武器演练 · 第3关 / 不计成绩</option><option value="p5">首领演练 · 第5关 砧塔 / 不计成绩</option><option value="p10">首领演练 · 第10关 血眼 / 不计成绩</option><option value="p15">后期演练 · 第15关 / 全武器</option><option value="build">构筑演练 · 三选一强化 / 不计成绩</option></select></label></div><div class="runner-stats"><div>本局分数<strong id="run-score">0</strong></div><div>当前关卡<strong id="run-level">01</strong></div><div>历史最高<strong id="run-best">0</strong></div><div><span id="run-progress-label">本关推进</span><strong id="run-next">0%</strong></div></div><div class="runner-combat-hud"><span>护盾 <b id="run-hp">4 / 4</b></span><span>击破 <b id="run-kills">00</b></span><span>首领 <b id="run-boss-kills">0</b></span></div><div class="runner-weapon-hud"><strong id="run-weapon">脉冲手枪</strong><span id="run-ammo">8 / 8</span><span id="run-reload-status">R 换弹</span><div id="run-reload-meter" role="progressbar" aria-label="换弹进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i></i></div></div><div class="runner-boss-hud" id="run-boss-hud" hidden><div><strong id="run-boss-name"></strong><span id="run-boss-phase"></span><b id="run-boss-hp"></b></div><div class="boss-health-track"><i id="run-boss-health"></i></div><p id="run-boss-action"></p></div><p id="run-arena-status" class="runner-arena-status" hidden></p><div class="runner-stage"><canvas id="runner-canvas" tabindex="0" role="img" aria-label="夜城射击跑酷。A D 移动，空格或 W 长短按跳跃，J X 射击，R 换弹，Q 切换武器，K 冲刺，E 修复，C EMP，P 暂停。"></canvas><div class="runner-overlay" id="runner-overlay"><strong id="runner-overlay-title">接入高危任务？</strong><p id="runner-overlay-copy">直线弹道 · 弹匣管理 · 每5关首领战</p></div></div><div class="runner-level-progress" aria-hidden="true"><i id="runner-level-fill"></i></div><section id="run-upgrades" class="runner-upgrades" aria-label="首领战奖励 三选一强化" hidden><p class="eyebrow" id="run-upgrade-label"></p><h3>植入一项强化</h3><p>时间已暂停。按 1 / 2 / 3 或选择卡片，接入下一关。</p><div id="run-perk-cards"></div></section><div class="runner-session-controls"><button class="button primary" id="run-start">开始任务 ▷</button><button class="small-button" id="run-pause" disabled>暂停 P</button><button class="small-button" id="run-finish" disabled>结束并记录</button><button class="small-button" id="run-retry-save" hidden>重试保存成绩</button></div><div class="runner-controls"><button class="small-button run-move" id="run-left" disabled aria-label="向左移动 A">← A</button><button class="small-button run-move" id="run-right" disabled aria-label="向右移动 D">D →</button><button class="button runner-jump" id="run-jump" disabled>按住高跳 ↑</button><button class="button runner-fire" id="run-fire" disabled>按住射击 J / X</button></div><div class="runner-tools"><button class="small-button" id="run-reload" disabled>换弹 R</button><button class="small-button" id="run-switch" disabled>武器 Q</button><button class="small-button" id="run-dash" disabled>冲刺 K</button><button class="small-button" id="run-heal" disabled>修复 / 第2关</button><button class="small-button" id="run-emp" disabled>EMP / 第4关</button><button class="small-button" id="run-drop" disabled>下落 S</button></div><div class="runner-arsenal" id="run-arsenal" role="group" aria-label="武器与解锁进度"></div><p id="run-status" role="status">A / D 移动；空格 / ↑ / W 点按低跳、长按高跳。J / X 射击，R 换弹，K 冲刺。</p><p id="run-build" class="runner-build">当前植入：无 · 每5关击败首领后三选一强化</p><details class="runner-guide"><summary>武器、首领与成绩规则 ↗</summary><p>共7种武器：L1手枪、L3散弹、L5磁爆榴弹、L6步枪、L8三叉脉冲、L9轨道枪、L12折光弹射器。按1—7或卡片直接选择，Q按解锁顺序切换。Q 或下方卡片切换，弹匣各自保留，换枪不会补弹。弹匣空后需 R 手动换弹；换弹时仍可移动、跳跃和冲刺。武器都不追踪。榴弹沿抛物线飞行并范围爆炸；三叉脉冲每次齐射消耗3发；折光弹最多反弹3次，可借地面、天花板和浮台改变路线。其他武器保留固定直线/散射弹道。</p><p>第2关获得修复针 E（恢复2格），第4关获得 EMP C（清弹幕并造成范围伤害）。每次击败首领补给一支修复针和一枚 EMP，最多各3。K / Shift 冲刺持续0.35秒，速度500，未触及边界时位移约175；按住A/D决定方向，未按默认向右。起步0.05秒与收尾0.05秒不保护，仅中间0.25秒无敌，基础冷却2.6秒。敌人随关卡增加护甲、密度，第4关起部分敌人会蓄力射击。</p><p>每5关强制首领战。砧塔：冲击波、扇射、延时地雷、低位激光、抛射炮击、锁高光束；血眼：扇射、光柱、环形弹、弹雨、十字锁定、阶梯箭雨。工业炉与光学实验场各有3座单向浮台，可从下方跳穿；落脚后3秒崩解，离开再踩也不会重置，5秒后重组。S/↓或下落按钮穿过当前浮台。浮台提供高度变化，不会阻挡弹幕或激光。平台不是永久安全区，第二阶段增加弹量和密度。观察红色预警，A/D离开光柱、跳过地面攻击或用冲刺穿过弹幕。半血进入第二阶段。击败后才能选择强化并继续；击破分不会跳过关卡。</p><p>强化仅限本局，可在下方查看已选词条。正式成绩保存分数、关卡、击破与首领数，最近十局和最高分仅存在当前浏览器；旧版记录标「旧」。演练不计成绩。切后台自动暂停；关闭窗口退出本局，未结算不保存。角色、首领与美术由代码原创绘制，阵营与动作节奏参考赛博朋克、茶杯头和死亡细胞风格。</p></details><div class="runner-records"><h3>最近十局 <small>正式模式 / 本浏览器保存</small></h3><div id="runner-record-list"></div></div></div>`;
    const opened=await Night.motion.openDialog(dialog);if(!opened||scope!==own||own.signal.aborted){if(scope===own)close();return;}
