    api.weapons.forEach((w,i)=>{const b=document.createElement('button');b.className='small-button';b.dataset.weapon=i;b.textContent=(i+1)+' / '+w.name+' · L'+w.level;b.setAttribute('aria-pressed','false');$('#run-arsenal').append(b);});
    function records(){return api.cleanRecords(Night.store.read('runner-records',{}));}
    function renderRecords(){const data=records();$('#run-best').textContent=data.best;const list=$('#runner-record-list');list.replaceChildren();if(!data.runs.length){list.textContent='完成正式任务，留下你的记录。';return;}const table=document.createElement('table');table.innerHTML='<thead><tr><th>分数</th><th>关卡</th><th>击破</th><th>首领</th><th>记录时间</th></tr></thead>';const body=document.createElement('tbody');data.runs.forEach(r=>{const tr=document.createElement('tr');[r.score+(r.rules==='legacy'?' · 旧':''),r.level,r.kills,r.bosses,new Date(r.date).toLocaleString('zh-CN')].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td);});body.append(tr);});table.append(body);list.append(table);}
