      $('#run-score').textContent=state.score;$('#run-level').textContent=String(state.level).padStart(2,'0');$('#run-next').textContent=state.stage==='boss'?'首领封锁':Math.min(100,Math.floor(state.progress/24))+'%';$('#runner-level-fill').style.width=state.stage==='boss'?'100%':state.progress/24+'%';
      $('#run-hp').textContent=state.hp+' / '+state.maxHp;$('#run-hp').dataset.low=state.hp<=1;$('#run-kills').textContent=String(state.kills).padStart(2,'0');$('#run-boss-kills').textContent=state.bossKills;$('#run-weapon').textContent=w.name;$('#run-ammo').textContent=ammo+' / '+model.capacity();$('#run-ammo').dataset.empty=ammo===0;$('#run-reload-status').textContent=state.reloadLeft>0?'换弹 '+state.reloadLeft.toFixed(1)+'s':ammo<(w.cost||1)?'余弹不足 / 按 R':w.kind==='grenade'?'抛射 / 范围爆炸':w.kind==='ricochet'?'折射 / 最多3次':w.cost?'三发齐射 / 消耗3弹':'固定弹道 / R 换弹';const progress=state.reloadLeft>0?100*(1-state.reloadLeft/state.reloadTotal):0;$('#run-reload-meter').setAttribute('aria-valuenow',Math.round(progress));$('#run-reload-meter i').style.width=progress+'%';
      $('#run-arena-status').hidden=!state.platforms.length;$('#run-arena-status').textContent=state.platforms.map(p=>p.id+' '+(p.active?(p.armed?p.left.toFixed(1)+'s':'待机3s'):'重组'+p.cooldown.toFixed(1)+'s')).join(' ｜ ')+' · S / ↓ 下落';$('#run-drop').disabled=!running||!state.platforms.some(p=>p.active&&p.id===state.player.support);
      const boss=state.boss;$('#run-boss-hud').hidden=!boss;if(boss){$('#run-boss-name').textContent=boss.name;$('#run-boss-phase').textContent='PHASE '+boss.phase+' / '+({intro:'接近中',telegraph:'攻击预警',attack:'出招',recover:'恢复空档'}[boss.state]);$('#run-boss-hp').textContent=Math.ceil(boss.hp)+' / '+boss.maxHp;$('#run-boss-health').style.width=boss.hp/boss.maxHp*100+'%';$('#run-boss-action').textContent=attackText[boss.pattern];}
      $('#run-mode').disabled=active;$('#run-start').disabled=active;$('#run-start').textContent=state.mode==='over'?'重新出击 ↻':'开始任务 ▷';$('#run-pause').disabled=!['running','paused'].includes(state.mode);$('#run-pause').textContent=state.mode==='paused'?'继续 P':'暂停 P';$('#run-finish').disabled=!active;$('#run-finish').textContent=state.practice?'结束演练':'结束并记录';
      for(const id of ['run-jump','run-left','run-right'])$('#'+id).disabled=!running;$('#run-fire').disabled=!running||state.reloadLeft>0;$('#run-fire').textContent=ammo<(w.cost||1)?'余弹不足 / R 换弹':'按住射击 J / X';$('#run-reload').disabled=!running||state.reloadLeft>0||ammo>=model.capacity();$('#run-switch').disabled=!running||state.reloadLeft>0||state.level<3;$('#run-dash').disabled=!running||state.dashCooldown>0;$('#run-dash').dataset.phase=state.dashLeft>0?(state.dashProtected?'immune':'edge'):'ready';$('#run-dash').textContent=state.dashLeft>0?(state.dashProtected?'冲刺 · 无敌':'冲刺 · 过渡'):state.dashCooldown>0?'冲刺 '+state.dashCooldown.toFixed(1)+'s':'冲刺 K';$('#run-heal').disabled=!running||state.level<2||state.meds<=0||state.hp>=state.maxHp;$('#run-heal').textContent=state.level<2?'修复 / L2':'修复 E ×'+state.meds;$('#run-emp').disabled=!running||state.level<4||state.emps<=0;$('#run-emp').textContent=state.level<4?'EMP / L4':'EMP C ×'+state.emps;
