    function draw(){Night.runnerPaint(ctx,canvas,state);}
    function resize(){const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.max(1,Math.round(canvas.clientWidth*dpr));canvas.height=Math.max(1,Math.round(canvas.clientHeight*dpr));draw();}
